WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK;
ALTER SESSION SET CONTAINER=FREEPDB1;
DECLARE
 PROCEDURE add_col(owner_name VARCHAR2,table_name_in VARCHAR2,column_name_in VARCHAR2,definition VARCHAR2) IS n NUMBER;
 BEGIN SELECT COUNT(*) INTO n FROM ALL_TAB_COLUMNS WHERE OWNER=owner_name AND TABLE_NAME=table_name_in AND COLUMN_NAME=column_name_in;
  IF n=0 THEN EXECUTE IMMEDIATE 'ALTER TABLE '||owner_name||'.'||table_name_in||' ADD ('||column_name_in||' '||definition||')';END IF;
 END;
BEGIN
 add_col('CF_APPLICATION','CF_APPLICATIONS','PHASE0_JSON','CLOB');
 add_col('CF_ELIGIBILITY','FINANCIAL_IMPORT_BATCH','CREDIT_SCORE_BAND','VARCHAR2(20) DEFAULT ''NOT_AVAILABLE'' NOT NULL');
 add_col('CF_ELIGIBILITY','LENDER_PRODUCT_RULE','MIN_CREDIT_SCORE_BAND','VARCHAR2(20) DEFAULT ''FAIR'' NOT NULL');
 add_col('CF_ELIGIBILITY','LENDER_PRODUCT_RULE','MAX_REPAYMENT_PERCENT','NUMBER(7,4) DEFAULT 40 NOT NULL');
 add_col('CF_ELIGIBILITY','LENDER_PRODUCT_RULE','ASSESSMENT_APR_PERCENT','NUMBER(7,4) DEFAULT 18 NOT NULL');
 add_col('CF_ELIGIBILITY','ELIGIBILITY_EVALUATION','CREDIT_SCORE_BAND','VARCHAR2(20)');
 add_col('CF_ELIGIBILITY','ELIGIBILITY_EVALUATION','MONTHLY_SURPLUS','NUMBER(19,2)');
 add_col('CF_ELIGIBILITY','ELIGIBILITY_LENDER_RESULT','ESTIMATED_MONTHLY_PAYMENT','NUMBER(19,2)');
END;
/
DECLARE n NUMBER; BEGIN
 SELECT COUNT(*) INTO n FROM ALL_CONSTRAINTS WHERE OWNER='CF_APPLICATION' AND CONSTRAINT_NAME='CK_CF_APP_STATUS';
 IF n>0 THEN EXECUTE IMMEDIATE 'ALTER TABLE CF_APPLICATION.CF_APPLICATIONS DROP CONSTRAINT CK_CF_APP_STATUS';END IF;
 EXECUTE IMMEDIATE 'ALTER TABLE CF_APPLICATION.CF_APPLICATIONS ADD CONSTRAINT CK_CF_APP_STATUS CHECK(STATUS IN (''DRAFT'',''SUBMITTED'',''ACTION_REQUIRED'',''CHECK_FAILED'',''ELIGIBILITY_CHECKING'',''NOT_ELIGIBLE'',''READY_FOR_LENDER'',''SUBMITTING'',''UNDER_REVIEW'',''MANUAL_REVIEW'',''APPROVED'',''OFFER_ACCEPTED'',''OFFER_DECLINED'',''OFFER_EXPIRED'',''REJECTED'',''CANCELLED'',''AWAITING_CONSENT'',''VERIFYING'',''NO_ELIGIBLE_LENDER'',''LENDER_REVIEW'',''INFORMATION_REQUIRED'',''OFFER_AVAILABLE''))';
END;
/
-- Rename current-state labels consistently; retain historical outbox/audit payloads without changes.
UPDATE CF_APPLICATION.CF_APPLICATIONS SET STATUS=CASE STATUS WHEN 'AWAITING_CONSENT' THEN 'DRAFT' WHEN 'VERIFYING' THEN 'SUBMITTED' WHEN 'NO_ELIGIBLE_LENDER' THEN 'NOT_ELIGIBLE' WHEN 'LENDER_REVIEW' THEN 'UNDER_REVIEW' WHEN 'INFORMATION_REQUIRED' THEN 'ACTION_REQUIRED' WHEN 'OFFER_AVAILABLE' THEN 'APPROVED' ELSE STATUS END;
UPDATE CF_ORCHESTRATION.CF_WORKFLOW SET STATUS=CASE STATUS WHEN 'AWAITING_CONSENT' THEN 'DRAFT' WHEN 'VERIFYING' THEN 'SUBMITTED' WHEN 'NO_ELIGIBLE_LENDER' THEN 'NOT_ELIGIBLE' WHEN 'LENDER_REVIEW' THEN 'UNDER_REVIEW' WHEN 'INFORMATION_REQUIRED' THEN 'ACTION_REQUIRED' WHEN 'OFFER_AVAILABLE' THEN 'APPROVED' ELSE STATUS END;
DECLARE n NUMBER;BEGIN
 SELECT COUNT(*) INTO n FROM ALL_INDEXES WHERE OWNER='CF_APPLICATION' AND INDEX_NAME='UQ_CF_ACTIVE_PURPOSE';
 IF n=0 THEN EXECUTE IMMEDIATE 'CREATE UNIQUE INDEX CF_APPLICATION.UQ_CF_ACTIVE_PURPOSE ON CF_APPLICATION.CF_APPLICATIONS (CASE WHEN STATUS NOT IN (''CHECK_FAILED'',''NOT_ELIGIBLE'',''NO_ELIGIBLE_LENDER'',''OFFER_ACCEPTED'',''OFFER_DECLINED'',''OFFER_EXPIRED'',''REJECTED'',''CANCELLED'') THEN SELLER_ID END,CASE WHEN STATUS NOT IN (''CHECK_FAILED'',''NOT_ELIGIBLE'',''NO_ELIGIBLE_LENDER'',''OFFER_ACCEPTED'',''OFFER_DECLINED'',''OFFER_EXPIRED'',''REJECTED'',''CANCELLED'') THEN LOAN_PURPOSE END)';END IF;
END;
/
MERGE INTO CF_AUTH.CF_ORGANIZATIONS O USING(SELECT 'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb3' ID FROM DUAL) S ON(O.ORGANIZATION_ID=S.ID) WHEN NOT MATCHED THEN INSERT(ORGANIZATION_ID,ORGANIZATION_NAME,ORGANIZATION_TYPE) VALUES(S.ID,'Bank C','LENDER');
MERGE INTO CF_ELIGIBILITY.LENDER_PRODUCT_RULE R USING(SELECT 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3' ID FROM DUAL) S ON(R.PRODUCT_ID=S.ID AND R.RULE_VERSION=1) WHEN NOT MATCHED THEN INSERT(PRODUCT_ID,RULE_VERSION,LENDER_ID,PRODUCT_NAME,MIN_AGE_MONTHS,MIN_AVERAGE_NET,MAX_RETURN_PERCENT,MIN_AMOUNT,MAX_AMOUNT,SALES_MULTIPLIER,ROUTING_PRIORITY,ACTIVE,MIN_CREDIT_SCORE_BAND,MAX_REPAYMENT_PERCENT,ASSESSMENT_APR_PERCENT) VALUES(S.ID,1,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbb3','Bank C Business Credit',6,60000,20,10000,500000,1.5,3,1,'FAIR',35,20);
MERGE INTO CF_ELIGIBILITY.LENDER_PRODUCT_HEAD H USING(SELECT 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3' ID FROM DUAL) S ON(H.PRODUCT_ID=S.ID) WHEN NOT MATCHED THEN INSERT(PRODUCT_ID,CURRENT_VERSION) VALUES(S.ID,1);
BEGIN FOR p IN (SELECT 'WORKING_CAPITAL' V FROM DUAL UNION ALL SELECT 'PURCHASE_INVENTORY' FROM DUAL UNION ALL SELECT 'BUSINESS_EXPANSION' FROM DUAL) LOOP
 MERGE INTO CF_ELIGIBILITY.LENDER_PRODUCT_PURPOSE T USING(SELECT 'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3' ID, p.V PURPOSE FROM DUAL) S ON(T.PRODUCT_ID=S.ID AND T.RULE_VERSION=1 AND T.PURPOSE=S.PURPOSE) WHEN NOT MATCHED THEN INSERT(PRODUCT_ID,RULE_VERSION,PURPOSE) VALUES(S.ID,1,S.PURPOSE);
 END LOOP;END;
/
COMMIT;
EXIT;
